    PlayerVitalOptions Options(EnergyConfiguration c){return mana?c.PlayerMana:c.PlayerHealth;}
    void Change(Action<PlayerVitalOptions> apply){if(loading||released)return;var c=owner.Configuration;var o=Options(c);apply(o);o.Normalize();owner.ApplyConfiguration(c);}
    void Select(int tab){selected=tab;for(int i=0;i<3;i++){pages[i].Visibility=i==tab?Visibility.Visible:Visibility.Collapsed;tabs[i].Background=SettingsVisual.Brush(i==tab?"#383A4659":"#0CFFFFFF");}if(scroll!=null)scroll.ScrollToTop();}
    StackPanel Group(int tab,string name){pages[tab].Children.Add(SettingsVisual.Text(name,11,"#929CAD"));var content=new StackPanel();var card=SettingsVisual.Card(content,new Thickness(16,4,16,4));card.Margin=new Thickness(0,6,0,16);pages[tab].Children.Add(card);return content;}
    Grid Row(string label){var row=new Grid{Margin=new Thickness(0,6,0,6),MinHeight=38};row.ColumnDefinitions.Add(new ColumnDefinition());row.ColumnDefinitions.Add(new ColumnDefinition{Width=GridLength.Auto});var text=SettingsVisual.Text(label);text.VerticalAlignment=VerticalAlignment.Center;text.Margin=new Thickness(0,0,12,0);row.Children.Add(text);return row;}
    void Check(StackPanel group,string label,Func<PlayerVitalOptions,bool> get,Action<PlayerVitalOptions,bool> set){var row=Row(label);var control=new CheckBox();AutomationProperties.SetName(control,label);Grid.SetColumn(control,1);row.Children.Add(control);group.Children.Add(row);control.Click+=delegate{Change(o=>set(o,control.IsChecked==true));};reloaders.Add(o=>control.IsChecked=get(o));}
    void Number(StackPanel group,string key,string label,string unit,decimal min,decimal max,int decimals,decimal step,Func<PlayerVitalOptions,decimal> get,Action<PlayerVitalOptions,decimal> set){var row=Row(label);var side=new StackPanel{Orientation=Orientation.Horizontal};Grid.SetColumn(side,1);row.Children.Add(side);var number=new SettingsNumber(label,min,max,decimals,step);numbers[key]=number;side.Children.Add(number);side.Children.Add(new TextBlock{Text=unit,Width=28,Margin=new Thickness(7,0,0,0),VerticalAlignment=VerticalAlignment.Center,Foreground=SettingsVisual.Brush("#8994A6")});group.Children.Add(row);number.Changed+=delegate{Change(o=>set(o,number.Value));};reloaders.Add(o=>number.Value=get(o));}
    void Color(StackPanel group,string label,Func<PlayerVitalOptions,string> get,Action<PlayerVitalOptions,string> set,Func<PlayerVitalOptions,bool> available=null){var row=Row(label);var button=SettingsVisual.Button("",delegate{var picker=new HelperColorPicker(get(Options(owner.Configuration)),label,owner.Language){Owner=window};if(picker.ShowDialog()==true)Change(o=>set(o,picker.SelectedHex));});button.MinWidth=145;Grid.SetColumn(button,1);row.Children.Add(button);group.Children.Add(row);reloaders.Add(o=>{var value=get(o);button.Content=new Border{Background=SettingsVisual.Brush(value),CornerRadius=new CornerRadius(4),Width=95,Height=16};button.ToolTip=value;button.IsEnabled=o.Bar.Enabled&&(available==null||available(o));});}
    void TextGroup(string title,int index){var group=Group(1,title);Check(group,"Show text",o=>o.Text(index).Enabled,(o,v)=>o.Text(index).Enabled=v);Check(group,"Bold text",o=>o.Text(index).Bold,(o,v)=>o.Text(index).Bold=v);Number(group,"TextSize"+index,"Text size","px",10,96,0,1,o=>o.Text(index).FontSize,(o,v)=>o.Text(index).FontSize=(int)v);Color(group,"Text color",o=>o.Text(index).Color,(o,v)=>o.Text(index).Color=v);
        if(index==2)Check(group,"Keep maximum next to current value",o=>o.MaximumBesideCurrent,(o,v)=>o.MaximumBesideCurrent=v);var row=Row("Text position");var position=new ComboBox{Width=190,Height=34};foreach(string text in new[]{"Above · left","Above · center","Above · right","Below · left","Below · center","Below · right"})position.Items.Add(new ComboBoxItem{Content=text});Grid.SetColumn(position,1);row.Children.Add(position);group.Children.Add(row);position.SelectionChanged+=delegate{Change(o=>o.Text(index).Position=position.SelectedIndex);};reloaders.Add(o=>{position.SelectedIndex=o.Text(index).Position;position.IsEnabled=index!=2||!o.MaximumBesideCurrent||!o.Current.Enabled;});
        Number(group,"TextX"+index,"Horizontal text offset","px",-600,600,0,1,o=>o.Text(index).OffsetX,(o,v)=>o.Text(index).OffsetX=(int)v);Number(group,"TextY"+index,"Vertical text offset","px",-600,600,0,1,o=>o.Text(index).OffsetY,(o,v)=>o.Text(index).OffsetY=(int)v);Check(group,"Black text outline",o=>o.Text(index).Outline.Enabled,(o,v)=>o.Text(index).Outline.Enabled=v);Number(group,"OutlineWidth"+index,"Outline thickness","px",1,8,0,1,o=>o.Text(index).Outline.Width,(o,v)=>o.Text(index).Outline.Width=(int)v);Number(group,"OutlineOpacity"+index,"Outline opacity","%",0,100,0,5,o=>o.Text(index).Outline.Opacity,(o,v)=>o.Text(index).Outline.Opacity=(int)v);
