    internal void Reload(){if(released)return;var o=Options(owner.Configuration);if(saved!=null&&PlayerVitalOptions.Same(saved,o)&&language==owner.Language)return;loading=true;try{enabled.IsChecked=o.Bar.Enabled;foreach(var reload in reloaders)reload(o);previewSlider.Value=o.PreviewPercent;previewValue.Text=o.PreviewPercent+" %";preview.Opacity=o.Opacity/100.0;scroll.IsEnabled=o.Bar.Enabled;scroll.Opacity=o.Bar.Enabled?1:.45;using(var surface=PlayerVitalDesign.Render(o,mana,o.PreviewPercent/100.0,false))preview.Source=SettingsVisual.Bitmap(surface.Bitmap);UpdateStatus();UiLanguage.Apply(this,owner.Language);language=owner.Language;saved=o.Copy();}finally{loading=false;}}
    internal void Release(){released=true;preview.Source=null;saved=null;}
    void TestNumber(string key,string value){((TextBox)numbers[key].Children[1]).Text=value;numbers[key].Commit();}
    internal void Verify(string root){var original=owner.Configuration;var c=original.Copy();Options(c).Bar.Enabled=true;owner.ApplyConfiguration(c);Reload();var before=preview.Source;for(int i=0;i<100;i++)Reload();if(!object.ReferenceEquals(before,preview.Source))throw new Exception("Unchanged vital preview must be cached");foreach(int value in new[]{0,25,75,100}){var previous=preview.Source;previewSlider.Value=value;Reload();if(Options(owner.Configuration).PreviewPercent!=value||previewValue.Text!=value+" %"||object.ReferenceEquals(previous,preview.Source))throw new Exception("HP/MP preview slider updates stored sample, label and image");}TestNumber("TextSize1","30");if(Options(owner.Configuration).Current.FontSize!=30||Options(owner.Configuration).Maximum.FontSize!=16)throw new Exception("Current and max fonts are independent");TestNumber("TextY2","15");if(Options(owner.Configuration).Maximum.OffsetY!=15)throw new Exception("Independent maximum offset");owner.UndoConfiguration();if(Options(owner.Configuration).Maximum.OffsetY==15)throw new Exception("Vitals undo");Select(1);SettingsVisual.RenderPreview(window,Path.Combine(root,"designs",mana?"settings-player-mp.png":"settings-player-health.png"));owner.ApplyConfiguration(original);Reload();Select(0);}
